package pzvrphysicality;

import java.lang.reflect.Field;import java.util.*;import local.pzvr.*;import viewpoint.core.Frame;import viewpoint.render.ModelDraws;import viewpointvr.physics.CollisionShape;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.core.skinnedmodel.model.*;

/** Exact, current held prop records only. No graphics, inventory, socket or bone matrix is modified here. */
public final class HeldContactCapture {
 public record Sample(IsoPlayer actor,InventoryItem item,ModelInstance instance,ModelMesh mesh,ItemMeshCpu.Data geometry,int side,Object scene,XrBackend.Frame input,long rigGeneration,long time,double units,float mass,CollisionShape shape,float[] target){public Sample{target=target.clone();}public float[] target(){return target.clone();}}
 private record Access(Field meshes,Field instances,Field values){}
 private static Access access;private static volatile List<Sample> latest=List.of();private static String status="Held props waiting";
 public static boolean prop(IsoPlayer actor,InventoryItem item,int side){return actor!=null&&IsoPlayer.players.length>0&&actor==IsoPlayer.players[0]&&item!=null&&side>=0&&side<2&&NativeItems.hand(actor,side)==item&&NativeItems.hand(actor,1-side)!=item&&item.getContainer()==actor.getInventory()&&actor.getInventory().contains(item)&&item.getWorldItem()==null&&!(item instanceof zombie.inventory.types.HandWeapon)&&!item.isRequiresEquippedBothHands()&&!item.isForceDropHeavyItem()&&!actor.hasTimedActions()&&!NativeBody.ownsGrip(side)&&!BackpackContents.ownsGrip(side)&&!(BackpackContents.enabled()&&item instanceof zombie.inventory.types.InventoryContainer)&&!(NativeConsumption.enabled()&&(item instanceof zombie.inventory.types.Food||UtensilCapture.supportedTool(item)||UtensilCapture.supportedFood(item)))&&NativeItems.supportsPhysicalGestures(actor)&&VrControls.supportedPistol==null;}
 private static Access access()throws ReflectiveOperationException{if(access==null)access=new Access(field("meshes"),field("instances"),field("values"));return access;}private static Field field(String name)throws ReflectiveOperationException{var value=ModelDraws.class.getDeclaredField(name);value.setAccessible(true);return value;}
 public static List<Sample> capture(Frame frame,IsoPlayer actor){latest=List.of();if(!HeldContactDriver.enabled()||!Main.ready()||frame==null||actor==null)return latest;long now=System.nanoTime();var rig=WorldRigCapture.forScene(frame.scene,now);var input=Engine.latestInput;if(rig==null||rig.actor()!=actor||!rig.fresh(now)||input==null||!input.focused()||input.time()!=rig.inputTime()||Math.abs(frame.camX-rig.camera().x())>.0001||Math.abs(frame.camY-rig.camera().y())>.0001||Math.abs(frame.camZ*Math.sqrt(6)-rig.camera().height())>.0001){status="Held props waiting for matching rig input";return latest;}try{var a=access();var draws=frame.scene.models;int count=draws.count();var meshes=(ModelMesh[])a.meshes.get(draws);var instances=(ModelInstance[])a.instances.get(draws);var rows=(float[])a.values.get(draws);if(count<0||count>4096||count>meshes.length||count>instances.length||count>rows.length/68)throw new IllegalArgumentException("Held draw packet budget");var result=new ArrayList<Sample>();for(int side=0;side<2;side++){var item=NativeItems.hand(actor,side);var hand=rig.hand(side);var raw=side==0?input.left():input.right();if(!prop(actor,item,side)||hand==null||raw==null||!raw.tracked()||raw.grip()==null)continue;var instance=side==0?actor.secondaryHandModel:actor.primaryHandModel;if(instance==null||instance.model==null||!instance.sub.isEmpty())continue;int found=-1;for(int n=0;n<count;n++)if(instances[n]==instance){if(found!=-1){found=-2;break;}found=n;}if(found<0)continue;var mesh=meshes[found];var data=ItemMeshCpu.get(mesh);if(mesh==null||data==null||!mesh.isReady()||mesh.skinningData!=null||instance.model.mesh!=mesh)continue;float mass=item.getActualWeight();if(!Float.isFinite(mass)||mass<=0||mass>20)continue;mass=Math.max(.01f,mass);var matrix=Arrays.copyOfRange(rows,found*68,found*68+16);var shape=HeldContactGeometry.shape(data,matrix,rig,hand);result.add(new Sample(actor,item,instance,mesh,data,side,frame.scene,input,rig.generation(),now,hand.units(),mass,shape,HeldContactGeometry.pose(hand)));}if(input!=Engine.latestInput||!input.focused())return latest;latest=List.copyOf(result);status=latest.isEmpty()?"No supported current rigid held prop":"Exact held rigid props ready: "+latest.size();}catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){latest=List.of();status="Held prop geometry unavailable";}return latest;}
 public static boolean current(Sample value,long now){if(value==null||now<value.time||now-value.time>150_000_000L||!prop(value.actor,value.item,value.side))return false;var input=Engine.latestInput;var rig=WorldRigCapture.latest;return input==value.input&&input.focused()&&rig!=null&&rig.actor()==value.actor&&rig.scene()==value.scene&&rig.generation()==value.rigGeneration&&rig.fresh(now)&&(value.side==0?value.actor.secondaryHandModel:value.actor.primaryHandModel)==value.instance&&value.instance.model!=null&&value.instance.model.mesh==value.mesh&&value.instance.sub.isEmpty()&&value.mesh.isReady()&&value.mesh.skinningData==null&&ItemMeshCpu.get(value.mesh)==value.geometry;}
 public static String status(){return status;}public static void clear(){latest=List.of();status="Held prop geometry Off";}
 private HeldContactCapture(){}
}
